<template><div>
<div class="page-head"><div><h1>Good morning, {{ firstName }}.</h1><p>Your business cockpit: revenue, collections, profit, stock and customer risk in one view.</p></div><div class="action-row"><RouterLink to="/reports" class="btn btn-soft">Business insights</RouterLink><RouterLink to="/sales" class="btn btn-primary">+ New sale</RouterLink></div></div>
<div class="grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4">
<div v-for="m in metrics" :key="m.label" class="card metric"><div class="flex items-start justify-between"><div><div class="metric-label">{{m.label}}</div><div class="metric-value mt-2">{{m.money?money(m.value):format(m.value)}}</div></div><div class="h-9 w-9 rounded-xl bg-slate-50 grid place-items-center text-slate-500">{{m.icon}}</div></div><div class="metric-trend mt-3">{{m.note}}</div></div></div>
<div class="mt-5 grid grid-cols-1 gap-4 xl:grid-cols-[1.45fr_1fr]">
<div class="card p-5"><div class="flex items-center justify-between"><div><h2 class="font-bold text-sm">Sales performance</h2><p class="text-[11px] text-slate-400 mt-1">Last 7 days</p></div><span class="status status-success">Live</span></div><div class="mt-7 flex h-52 items-end gap-2 sm:gap-3"><div v-for="d in daily" :key="d.day" class="flex h-full flex-1 flex-col justify-end"><div class="mx-auto w-full max-w-12 rounded-t-lg bg-gradient-to-t from-slate-900 to-indigo-400 transition-all dark:from-indigo-500 dark:to-cyan-300" :style="{height:`${barHeight(d.total)}%`}" :title="money(d.total)"></div><div class="mt-2 text-center text-[9px] text-slate-400">{{day(d.day)}}</div></div></div></div>
<div class="card p-5"><div class="flex items-center justify-between"><div><h2 class="font-bold text-sm">Collection risk</h2><p class="text-[11px] text-slate-400 mt-1">Receivables requiring action</p></div><RouterLink to="/reports/receivables" class="text-[11px] font-bold text-indigo-600">Open report →</RouterLink></div><div class="mt-6 space-y-5"><div><div class="flex justify-between text-[11px] mb-2"><span class="text-slate-500">Overdue</span><b>{{money(data.cards?.overdue)}}</b></div><div class="h-2 rounded-full bg-slate-100"><div class="h-2 rounded-full bg-rose-500" :style="{width:percent(data.cards?.overdue,data.cards?.receivables)}"></div></div></div><div><div class="flex justify-between text-[11px] mb-2"><span class="text-slate-500">Open invoices</span><b>{{format(data.cards?.open_invoices)}}</b></div><div class="rounded-xl bg-slate-50 p-3 text-[11px] text-slate-500 dark:bg-slate-800/50">{{data.cards?.receivables? 'Customer balances are actively tracked against invoices and payments.':'No outstanding customer balances.'}}</div></div></div></div></div>
<div class="mt-4 grid grid-cols-1 gap-4 lg:grid-cols-2">
<div class="card overflow-hidden"><div class="flex items-center justify-between px-5 py-4"><div><h2 class="font-bold text-sm">Top clients</h2><p class="text-[11px] text-slate-400 mt-1">Highest sales this month</p></div><RouterLink to="/clients" class="btn btn-soft">Clients</RouterLink></div><table class="data-table"><thead><tr><th>Client</th><th class="text-right">Sales</th></tr></thead><tbody><tr v-for="c in data.top_clients||[]" :key="c.id"><td>{{c.name}}</td><td class="text-right">{{money(c.sales_total)}}</td></tr><tr v-if="!(data.top_clients||[]).length"><td colspan="2"><div class="empty">No client sales yet.</div></td></tr></tbody></table></div>
<div class="card overflow-hidden"><div class="flex items-center justify-between px-5 py-4"><div><h2 class="font-bold text-sm">Stock watch</h2><p class="text-[11px] text-slate-400 mt-1">Products at minimum level</p></div><RouterLink to="/reports/inventory" class="btn btn-soft">Inventory</RouterLink></div><table class="data-table"><thead><tr><th>Product</th><th>Stock</th><th>Status</th></tr></thead><tbody><tr v-for="p in data.low_stock_items||[]" :key="p.id"><td>{{p.name}}</td><td>{{p.stock_quantity}}</td><td><span class="status status-warning">Low</span></td></tr><tr v-if="!(data.low_stock_items||[]).length"><td colspan="3"><div class="empty">Stock levels look healthy.</div></td></tr></tbody></table></div></div>
<div class="card mt-4 overflow-hidden"><div class="flex items-center justify-between px-5 py-4"><div><h2 class="font-bold text-sm">Recent sales</h2><p class="text-[11px] text-slate-400 mt-1">Latest completed transactions</p></div><RouterLink to="/sales" class="btn btn-soft">All sales</RouterLink></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Sale</th><th>Client</th><th>Date</th><th>Total</th><th>Status</th></tr></thead><tbody><tr v-for="s in data.recent_sales||[]" :key="s.id"><td>{{s.sale_number}}</td><td>{{s.client?.name||'Walk-in'}}</td><td>{{formatDate(s.sale_date)}}</td><td>{{money(s.total)}}</td><td><StatusBadge :value="s.status"/></td></tr><tr v-if="!(data.recent_sales||[]).length"><td colspan="5"><div class="empty">No sales yet.</div></td></tr></tbody></table></div></div>
</div></template>
<script setup lang="ts">import {computed,onMounted,ref} from 'vue';import {api} from '../services/api';import StatusBadge from '../components/StatusBadge.vue';
import {formatDate as formatDisplayDate} from '../utils/date';const data=ref<any>({cards:{}});const authName=localStorage.getItem('mauzohub_name')||'there';const firstName=authName.split(' ')[0];const daily=computed(()=>data.value.daily_sales||[]);const maxDaily=computed(()=>Math.max(1,...daily.value.map((x:any)=>Number(x.total||0))));function money(v:any){return new Intl.NumberFormat('en-TZ',{style:'currency',currency:'TZS',maximumFractionDigits:0}).format(Number(v||0))}function format(v:any){return new Intl.NumberFormat('en-TZ').format(Number(v||0))}function formatDate(v:any){return formatDisplayDate(v)}function day(v:any){return new Intl.DateTimeFormat('en-TZ',{timeZone:'Africa/Dar_es_Salaam',weekday:'short'}).format(new Date(v)).slice(0,3)}function barHeight(v:any){return Math.max(8,Number(v||0)/maxDaily.value*100)}function percent(a:any,b:any){return `${Math.min(100,(Number(a||0)/Math.max(1,Number(b||0)))*100)}%`}const metrics=computed(()=>[{label:'Sales this month',value:data.value.cards?.sales_month,money:true,icon:'↗',note:'Gross completed sales'},{label:'Outstanding',value:data.value.cards?.receivables,money:true,icon:'◔',note:`${format(data.value.cards?.open_invoices)} open invoices`},{label:'Payments received',value:data.value.cards?.payments_month,money:true,icon:'₵',note:'Collections this month'},{label:'Low-stock items',value:data.value.cards?.low_stock,money:false,icon:'◈',note:'Needs replenishment'}]);onMounted(async()=>{try{data.value=(await api.get('/dashboard')).data}catch{}})</script>
